'use client'

import Image from 'next/image'
import Link from 'next/link'
import { Header } from '@/components/projects'
import { projects } from '@/app/works/projectlist'
import { ProjectGrid } from '@/app/works/ProjectGrid'

const STATEMENT =
  'I make folded typography: letters generated by code, unfolded into paper nets, and assembled by hand. My work asks what stays ours when a tool does the making, and extends into simulation and media art.'

// 접은 작업물 사진. slug는 projectlist.ts의 slug와 같아야 합니다.
const FOLDED_WORKS = [
  { src: '/images/projects/typofold/cover.jpg', w: 2468, h: 1918, title: 'TypoFold', slug: 'typofold' },
  { src: '/images/projects/daily-folding-practice/06.jpg', w: 3240, h: 2160, title: 'Daily Folding Practice', slug: 'daily-folding-practice' },
  { src: '/images/projects/daily-folding-practice/02.jpg', w: 1620, h: 2160, title: 'Daily Folding Practice', slug: 'daily-folding-practice' },
  { src: '/images/projects/typofold/33.jpg', w: 1097, h: 1371, title: 'TypoFold', slug: 'typofold' },
  { src: '/images/projects/daily-folding-practice/04.jpg', w: 1620, h: 2160, title: 'Daily Folding Practice', slug: 'daily-folding-practice' },
  { src: '/images/projects/weaving-letters/01.jpg', w: 2048, h: 1365, title: 'Weaving Letters', slug: 'weaving-letters' },
  { src: '/images/projects/daily-folding-practice/05.jpg', w: 1620, h: 2160, title: 'Daily Folding Practice', slug: 'daily-folding-practice' },
  { src: '/images/projects/typofold/34.jpg', w: 1097, h: 1371, title: 'TypoFold', slug: 'typofold' },
  { src: '/images/projects/daily-folding-practice/07.jpg', w: 1620, h: 2160, title: 'Daily Folding Practice', slug: 'daily-folding-practice' },
  { src: '/images/projects/daily-folding-practice/11.jpg', w: 1620, h: 2160, title: 'Daily Folding Practice', slug: 'daily-folding-practice' },
  { src: '/images/projects/typofold/25.jpg', w: 882, h: 1146, title: 'TypoFold', slug: 'typofold' },
  { src: '/images/projects/daily-folding-practice/08.jpg', w: 1620, h: 1080, title: 'Daily Folding Practice', slug: 'daily-folding-practice' },
]

// 접은 작업은 위 갤러리에서 보여주므로 아래 그리드에서는 TypoFold를 뺍니다.
const ARTIST_SKILLS = ['Media Art', 'Digital Fabrication'] as const

const artistProjects = [...projects]
  .filter((p) => p.slug !== 'typofold')
  .filter((p) => p.skills?.some((skill) => ARTIST_SKILLS.includes(skill as (typeof ARTIST_SKILLS)[number])))
  .sort((a, b) => Number(b.created_date) - Number(a.created_date))

export default function ArtistPage() {
  return (
    <>
      <Header title='Artist' />
      <main className='min-h-dvh w-full bg-white px-[30px] pb-[100px] pt-[60px] text-ink md:px-[40px] md:pt-[160px]'>
        <p className='max-w-[720px] text-title font-medium leading-snug text-black'>{STATEMENT}</p>

        <section className='mt-[80px]'>
          <h2 className='text-label font-medium text-black'>Folded Works</h2>
          <div className='mt-[24px] columns-2 gap-[16px] md:columns-3 md:gap-[24px]'>
            {FOLDED_WORKS.map((work) => (
              <Link
                key={work.src}
                href={`/works/${work.slug}`}
                className='group mb-[16px] block break-inside-avoid md:mb-[24px]'
              >
                <Image
                  src={work.src}
                  alt={`${work.title}: folded paper letters`}
                  width={work.w}
                  height={work.h}
                  sizes='(min-width: 768px) 33vw, 50vw'
                  className='h-auto w-full bg-neutral-100'
                />
                <span className='mt-[6px] block text-label text-neutral-500 group-hover:text-black'>{work.title}</span>
              </Link>
            ))}
          </div>
        </section>

        <section className='mt-[80px]'>
          <h2 className='text-label font-medium text-black'>Media Art &amp; Computer Graphics</h2>
          <ProjectGrid projects={artistProjects} />
        </section>
      </main>
    </>
  )
}
